pragma solidity ^0.8.24;

interface ICd2TokenS { function mint(address to, uint256 amount) external; }

/// @title Cd2VulnBridgeNoSourceCheck — LỖI: không kiểm srcChainId / địa chỉ cầu nguồn trong thông điệp.
contract Cd2VulnBridgeNoSourceCheck {
    ICd2TokenS public token;
    address public relayer;
    mapping(bytes32 => bool) public processed;

    event Released(bytes32 indexed msgId, address indexed to, uint256 amount);

    constructor(address _token, address _relayer) {
        token = ICd2TokenS(_token);
        relayer = _relayer;
    }

    /// @param srcBridge địa chỉ hợp đồng nguồn — BUG: không được so với cầu nguồn hợp lệ
    function release(bytes32 msgId, address to, uint256 amount, uint256 srcChainId, address srcBridge, bytes calldata sig) external {
        require(!processed[msgId], "processed");
        bytes32 h = keccak256(abi.encodePacked(msgId, to, amount, srcChainId, srcBridge));
        require(_recover(h, sig) == relayer, "bad signature");
        // BUG: thiếu require(srcChainId == TRUSTED_CHAIN && srcBridge == TRUSTED_BRIDGE)
        processed[msgId] = true;
        token.mint(to, amount);
        emit Released(msgId, to, amount);
    }

    function _recover(bytes32 h, bytes calldata sig) internal pure returns (address) {
        bytes32 d = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", h));
        (bytes32 r, bytes32 s, uint8 v) = (bytes32(sig[0:32]), bytes32(sig[32:64]), uint8(sig[64]));
        return ecrecover(d, v < 27 ? v + 27 : v, r, s);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ICd2TokenA { function mint(address to, uint256 amount) external; }

/// @title Cd2VulnBridgeAccess — LỖI: setRelayer() thiếu onlyOwner → ai cũng chiếm quyền relayer.
contract Cd2VulnBridgeAccess {
    ICd2TokenA public token;
    address public owner;
    address public relayer;
    mapping(bytes32 => bool) public processed;

    event Released(bytes32 indexed msgId, address indexed to, uint256 amount);
    event RelayerChanged(address indexed relayer);

    constructor(address _token, address _relayer) {
        token = ICd2TokenA(_token);
        owner = msg.sender;
        relayer = _relayer;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "only owner");
        _;
    }

    function setRelayer(address r) external { // BUG: thiếu onlyOwner
        relayer = r;
        emit RelayerChanged(r);
    }

    function release(bytes32 msgId, address to, uint256 amount) external {
        require(msg.sender == relayer, "only relayer");
        require(!processed[msgId], "processed");
        processed[msgId] = true;
        token.mint(to, amount);
        emit Released(msgId, to, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ICd2TokenO { function mint(address to, uint256 amount) external; }

/// @title Cd2VulnBridgeOracle — LỖI: tin giá từ MỘT oracle, không kiểm độ mới (stale) hay biên độ.
contract Cd2VulnBridgeOracle {
    ICd2TokenO public token;
    address public oracle;
    uint256 public price;      // giá tài sản nguồn (×1e2)
    uint256 public updatedAt;  // block cập nhật
    mapping(bytes32 => bool) public processed;

    event Released(bytes32 indexed msgId, address indexed to, uint256 amount);
    event PriceUpdated(uint256 price, uint256 at);

    constructor(address _token, address _oracle) {
        token = ICd2TokenO(_token);
        oracle = _oracle;
        price = 100;
        updatedAt = block.number;
    }

    function updatePrice(uint256 p) external {
        require(msg.sender == oracle, "only oracle");
        price = p; // BUG: không giới hạn biên độ thay đổi, một nguồn duy nhất
        updatedAt = block.number;
        emit PriceUpdated(p, block.number);
    }

    function release(bytes32 msgId, address to, uint256 srcAmount) external {
        require(!processed[msgId], "processed");
        // BUG: không require(block.number - updatedAt <= MAX_AGE)
        processed[msgId] = true;
        uint256 amount = (srcAmount * price) / 100;
        token.mint(to, amount);
        emit Released(msgId, to, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title Cd2VulnBridgeReentrancy — LỖI: unlock() chuyển ETH (gọi ra ngoài) TRƯỚC khi cập nhật số dư → reentrancy.
contract Cd2VulnBridgeReentrancy {
    mapping(address => uint256) public credit; // tài sản đã được relayer ghi có từ chuỗi kia
    address public relayer;

    event Credited(bytes32 indexed msgId, address indexed to, uint256 amount);
    event Unlocked(address indexed to, uint256 amount);

    constructor(address _relayer) payable {
        relayer = _relayer;
    }

    function credit_(bytes32 msgId, address to, uint256 amount) external {
        require(msg.sender == relayer, "only relayer");
        credit[to] += amount;
        emit Credited(msgId, to, amount);
    }

    function unlock() external {
        uint256 amount = credit[msg.sender];
        require(amount > 0, "nothing to unlock");
        (bool ok, ) = msg.sender.call{value: amount}(""); // BUG: tương tác ngoài trước khi cập nhật trạng thái
        require(ok, "transfer failed");
        credit[msg.sender] = 0; // BUG: hiệu ứng sau tương tác (vi phạm checks-effects-interactions)
        emit Unlocked(msg.sender, amount);
    }
}

